let speciesRelations=[],catalogue,credits=[],assetMap={},map,mapLoaded=false,terrainReady=false,imageReady=false,markerLayer=null,activeTrack=null,activeFeature=null,tourFrame=null,tourMarker=null,toastTimer,previousFocus=null;
