const tr=k=>copy[state.lang][k]??k;
const langText=x=>typeof x==='object'&&x!==null?(x[state.lang]||x.es||''):x;
const habitatName=k=>k==='forest'?(state.lang==='es'?'Bosques':'Forests'):k==='water'?tr('water'):(habitatLabels[k]?.[state.lang==='es'?0:1]||k);
const pname=p=>state.lang==='en'?p.name_en:p.name;
const rname=r=>state.lang==='en'?(r.name_en||routeEnglish[r.id]||r.name):r.name;
