const normal=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const formatN=(v,digits=1)=>v===null||v===undefined?'—':Number(v).toLocaleString(state.lang==='es'?'es-ES':'en-GB',{maximumFractionDigits:digits});
const duration=m=>m==null?'—':m<60?`${m} min`:`${Math.floor(m/60)} h${m%60?` ${m%60} min`:''}`;
const sourceLink=(id,label)=>{const s=catalogue.sources[id];return s?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${icon('external-link')}${esc(label||s.title)}</a>`:''};
const placeOf=id=>catalogue.places.find(p=>p.id===id);
const routeOf=id=>catalogue.routes.find(r=>r.id===id);
const speciesOf=id=>catalogue.species.find(s=>s.id===id);
