function metrics(r){if(r.activity_type==='guided_facility_visit')return `<div class="visit-metrics"><span>${icon('clock-3')}<strong>${duration(r.duration_minutes)}</strong> ${state.lang==='es'?'visita guiada':'guided visit'}</span><span>${icon('ticket')}${state.lang==='es'?'Reserva previa':'Advance booking'}</span></div>`;return `<div class="metrics"><div class="metric">${icon('route')}<strong>${formatN(r.distance_km,2)} <small>km</small></strong><span>${tr('distance')}</span></div><div class="metric">${icon('clock-3')}<strong>${duration(r.duration_minutes)}</strong><span>${tr('time')}</span></div><div class="metric">${icon('trending-up')}<strong>${r.ascent_m===null?'—':`+${formatN(r.ascent_m,0)} m`}</strong><span>${tr('elevation')}</span></div></div>`;}
