function renderLife(p){const sp=p.species_ids.map(speciesOf).filter(Boolean);let html=`<p>${tr('regionalPresence')}</p>`;if(sp.length)html+=`<div class="species-mini-grid">${sp.map(s=>`<button class="species-mini" data-action="species" data-id="${s.id}">${photo('species',s.id,sname(s))}<div><strong>${esc(sname(s))}</strong><em>${esc(s.scientific_name)}</em><span class="relation-label">${relationLabel(p.id,s.id)}</span></div></button>`).join('')}</div>`;else html+=note(tr('noSpecies'),'leaf');if(p.water.length)html+=`<h3>${tr('waterHere')}</h3><ul class="path-list">${p.water.map(w=>`<li>${icon('waves')}<span>${esc(w)}</span></li>`).join('')}</ul>`;html+=`<h3>${tr('habitats')}</h3><div class="fact-chips">${p.habitats.map(habitatChip).join('')}</div>${note(tr('observingText'),'binoculars')}`;return html}
