 if(!album)album=new NatureAlbum({catalogue,language:()=>state.lang,habitatName,speciesName:sname,langText,imageFile,photo,icon,showModal,header:modalHeader,placeName:pname,routeName:rname,routeOf,placeOf,naturalIndex:geographicIndex,ensureMap:showRealMap,naturalBounds:()=>geographicLayers?.viewBounds()||null,naturalName:r=>r[1]||naturalTypeName(r[2]),onNaturalMap:filters=>{closeModal();Object.assign(state,filters);$('#global-search').value=state.query;enterExplore('all');geographicLayers?.setType(state.naturalType);geographicLayers?.setQuery(state.query);},routeEligible:routeMatches,placeEligible:placeMatches,hasRouteFilters:()=>Boolean(state.profile||state.maxDistance||state.maxDuration||state.maxAscent||state.difficulty||state.withGeometry||state.activity==='cycling'),onResetFilters:resetFilters,isTaxonSaved:id=>isSaved('taxon',id),onSaveTaxon:(record,chunk)=>{state.savedTaxa[record.id]={id:record.id,scientific_name:record.scientific_name,common_name:record.common_name,group:record.group,chunk};toggleSaved('taxon',record.id);},onFilters:filters=>{Object.assign(state,filters);$('#global-search').value=state.query;if(state.view!=='home')renderSidebar();},onMap:filters=>{closeModal();Object.assign(state,filters);$('#global-search').value=state.query;enterExplore(filters.category||'all');},isOpen:()=>modalKind==='atlas'});
