 showModal('saved',modalHeader(tr('saved'),tr('saveLocal'),es?'LUGARES, VIDA Y RECORRIDOS':'PLACES, LIFE AND TRAILS')+`<div class="modal-body"><div class="saved-toolbar"><button class="button primary" data-action="draw">${icon('pencil-line')}${tr('draw')}</button><button class="button" data-action="import-gpx">${icon('upload')}${tr('importGpx')}</button><button class="button" data-action="preferences">${icon('sliders-horizontal')}${tr('profileButton')}</button><button class="button" data-action="export-notebook">${icon('download')}${tr('exportNotebook')}</button><button class="button" data-action="import-notebook">${icon('folder-open')}${tr('importNotebook')}</button></div><div class="notebook-collections"><label for="collection-select">${es?'Colección':'Collection'}</label><select id="collection-select">${option('',es?'Todos los guardados':'All saved items',state.activeCollection)}${state.collections.map(c=>option(c.id,c.name+' ('+c.keys.length+')',state.activeCollection)).join('')}</select>${collection?`<button class="link-button" data-action="delete-collection">${icon('folder-minus')}${es?'Quitar colección':'Remove collection'}</button>`:''}<form id="collection-form"><input name="name" required maxlength="60" placeholder="${es?'Nueva colección…':'New collection…'}" aria-label="${es?'Nombre de la colección':'Collection name'}"><button class="button" type="submit">${icon('plus')}${es?'Crear':'Create'}</button></form></div>${entries.length?`<div class="saved-grid">${cards}</div>`:`<div class="empty-state">${icon('bookmark')}<h3>${collection?(es?'Esta colección está vacía':'This collection is empty'):tr('emptySaved')}</h3><p>${es?'Guarda una ficha y añádela a tus colecciones.':'Save an entry and add it to your collections.'}</p><button class="button" data-action="atlas">${es?'Explorar el Atlas natural':'Explore the nature atlas'}</button></div>`}${state.drafts.length?`<div class="saved-section"><h3>${tr('drafts')}</h3><div class="saved-grid">${state.drafts.map(d=>`<article class="saved-card">${icon('route')}<div><h3>${esc(d.name)}</h3><p>${tr(d.kind==='manual'?'manual':'imported')} · ${formatN((d.segments||[d.coordinates]).reduce((total,segment)=>total+lineDistance(segment),0),2)} km</p><button data-action="view-draft" data-id="${d.id}">${tr('viewMap')}</button> · <button data-action="edit-draft" data-id="${d.id}">${state.lang==='es'?'Editar':'Edit'}</button> · <button data-action="export-draft" data-id="${d.id}">${tr('export')} GPX</button></div><button class="icon-button" data-action="delete-draft" data-id="${d.id}" aria-label="${tr('delete')}">${icon('trash-2')}</button></article>`).join('')}</div></div>`:''}</div>`);
