function haversine(a,b){const rad=Math.PI/180,dLat=(b[1]-a[1])*rad,dLng=(b[0]-a[0])*rad;const v=Math.sin(dLat/2)**2+Math.cos(a[1]*rad)*Math.cos(b[1]*rad)*Math.sin(dLng/2)**2;return 6371*2*Math.atan2(Math.sqrt(v),Math.sqrt(1-v))}
function lineDistance(points){if(!points||points.length<2)return 0;return points.slice(1).reduce((sum,p,i)=>sum+haversine(points[i],p),0)}
async function startDrawing(id=null){
 if(!await showRealMap())return;const original=state.drafts.find(d=>d.id===id);closeModal();closeDetail();enterExplore('all');state.drawing=true;state.editingDraftId=original?.id||null;state.draftGeometryChanged=false;state.drawUndo=[];state.drawSegments=original?(original.segments||[original.coordinates]).map(segment=>segment.map(c=>[...c])):[[]];state.drawSegment=0;state.drawPoints=state.drawSegments[0];state.selectedVertex=-1;$('#sidebar').hidden=true;$('#drawing-panel').hidden=false;
 $('#drawing-panel').innerHTML=`<h3>${state.lang==='es'?(original?'Editar recorrido':'Dibujar un recorrido'):(original?'Edit track':'Draw a track')}</h3><p>${state.lang==='es'?'Añade puntos en el mapa. Selecciona un vértice para moverlo o editar sus coordenadas. Los segmentos dibujados no verifican caminos ni accesos.':'Add points on the map. Select a vertex to move it or edit its coordinates. Drawn segments do not verify paths or access.'}</p><input id="draft-name" maxlength="90" value="${esc(original?.name||'')}" placeholder="${tr('draftName')}" aria-label="${tr('draftName')}"><div class="draft-segments"><label for="draft-segment">${state.lang==='es'?'Tramo':'Segment'}</label><select id="draft-segment">${state.drawSegments.map((_,i)=>option(i,String(i+1),0)).join('')}</select><button class="link-button" data-action="add-segment">${icon('plus')}${state.lang==='es'?'Nuevo tramo':'New segment'}</button></div><label class="draft-point-index">${state.lang==='es'?'Seleccionar vértice':'Select vertex'}<input type="number" id="draft-point-index" min="1" max="${state.drawPoints.length}" step="1" aria-label="${state.lang==='es'?'Número de vértice':'Vertex number'}"></label><div class="draft-vertex" id="draft-vertex" hidden><label>${state.lang==='es'?'Longitud':'Longitude'}<input type="number" id="vertex-lng" step="0.00001" min="-180" max="180"></label><label>${state.lang==='es'?'Latitud':'Latitude'}<input type="number" id="vertex-lat" step="0.00001" min="-90" max="90"></label><button class="icon-button" data-action="remove-vertex" aria-label="${state.lang==='es'?'Eliminar vértice':'Remove vertex'}">${icon('trash-2')}</button></div><p class="drawing-count" id="drawing-count"></p><div class="drawing-actions"><button class="button" data-action="undo-point">${icon('undo-2')}${tr('undo')}</button><button class="button primary" data-action="save-draft">${tr('saveDraft')}</button><button class="button" data-action="cancel-draw">${tr('cancel')}</button></div>`;
 updateDrawing();updateMarkers();map.getCanvas().style.cursor='crosshair';if(original)fitFeature({type:'MultiLineString',coordinates:state.drawSegments});else map.easeTo({padding:0,duration:reduced?0:500});icons();
}
function updateDrawing(preview=false){
 if(mapLoaded&&!preview){const features=[];state.drawSegments.forEach((segment,si)=>{if(segment.length>1)features.push({type:'Feature',properties:{},geometry:{type:'LineString',coordinates:segment}});if(si===state.drawSegment){const stride=Math.max(1,Math.ceil(segment.length/500));segment.forEach((c,i)=>{if(i%stride===0||i===state.selectedVertex||i===segment.length-1)features.push({type:'Feature',properties:{selected:i===state.selectedVertex},geometry:{type:'Point',coordinates:c}});});}});map.getSource('draft-route')?.setData({type:'FeatureCollection',features});map.getSource('draft-preview')?.setData({type:'FeatureCollection',features:[]});}
 if(mapLoaded&&preview&&state.selectedVertex>=0){const i=state.selectedVertex,points=state.drawPoints.slice(Math.max(0,i-1),i+2);map.getSource('draft-preview')?.setData({type:'FeatureCollection',features:[{type:'Feature',properties:{},geometry:{type:'Point',coordinates:state.drawPoints[i]}},...(points.length>1?[{type:'Feature',properties:{},geometry:{type:'LineString',coordinates:points}}]:[])]});}
 const pointIndex=$('#draft-point-index');if(pointIndex){pointIndex.max=state.drawPoints.length;pointIndex.value=state.selectedVertex>=0?String(state.selectedVertex+1):'';}const point=state.drawPoints[state.selectedVertex],vertex=$('#draft-vertex');if(vertex){vertex.hidden=!point;if(point){$('#vertex-lng').value=point[0].toFixed(5);$('#vertex-lat').value=point[1].toFixed(5);}}
 $('#drawing-count').textContent=`${state.drawSegments.reduce((n,seg)=>n+seg.length,0)} ${tr('points')} · ${formatN(state.drawSegments.reduce((n,seg)=>n+lineDistance(seg),0),2)} km · ${tr('drawDistance')}`;
}
function saveDraft(){
 const segments=state.drawSegments.filter(seg=>seg.length);if(!segments.length||segments.some(seg=>seg.length<2)){toast(tr('needPoints'));return;}
 const original=state.drafts.find(d=>d.id===state.editingDraftId),unchanged=original&&JSON.stringify(segments)===JSON.stringify(original.segments||[original.coordinates]),kind=unchanged?original.kind:'manual';const d={id:original?.id||makeId(),kind,name:$('#draft-name').value.trim()||tr('draftDefault'),coordinates:segments.flat(),segments,createdAt:original?.createdAt||new Date().toISOString(),modifiedAt:new Date().toISOString()};if(original&&!unchanged)d.edited_from_kind=original.kind;
 if(original)state.drafts[state.drafts.indexOf(original)]=d;else state.drafts.push(d);persist();cancelDraw();toast(tr('draftSaved'));renderSaved();
}
function cancelDraw(){finishVertexDrag();state.drawing=false;state.editingDraftId=null;$('#drawing-panel').hidden=true;$('#sidebar').hidden=false;if(mapLoaded)map.getCanvas().style.cursor='';clearTrack();updateMarkers();}
let vertexDrag=null,suppressDraftClick=false;
function rememberDraw(action){state.drawUndo.push({...action,segment:state.drawSegment});if(state.drawUndo.length>30)state.drawUndo.shift();}
function undoDraw(){const op=state.drawUndo.pop();if(!op)return;if(op.kind==='segment'){state.drawSegments.splice(op.segment,1);state.drawSegment=Math.max(0,op.segment-1);}else{state.drawSegment=op.segment;const points=state.drawSegments[op.segment];if(op.kind==='add')points.splice(op.index,1);if(op.kind==='remove')points.splice(op.index,0,op.point);if(op.kind==='move')points[op.index]=op.point;}state.drawPoints=state.drawSegments[state.drawSegment];state.selectedVertex=-1;$('#draft-segment').innerHTML=state.drawSegments.map((_,i)=>option(i,String(i+1),state.drawSegment)).join('');updateDrawing();}
function nearestVertex(point){let chosen=-1,best=18;const stride=Math.max(1,Math.ceil(state.drawPoints.length/500));for(let i=0;i<state.drawPoints.length;i+=stride){const p=map.project(state.drawPoints[i]),d=Math.hypot(p.x-point.x,p.y-point.y);if(d<best){chosen=i;best=d;}}if(state.selectedVertex>=0){const p=map.project(state.drawPoints[state.selectedVertex]);if(Math.hypot(p.x-point.x,p.y-point.y)<best)chosen=state.selectedVertex;}return chosen;}
function handleDrawingClick(e){if(!state.drawing)return;if(suppressDraftClick){suppressDraftClick=false;return;}const i=nearestVertex(e.point||map.project([e.lngLat.lng,e.lngLat.lat]));if(i>=0)state.selectedVertex=i;else{rememberDraw({kind:'add',index:state.drawPoints.length});state.drawPoints.push([e.lngLat.lng,e.lngLat.lat]);state.selectedVertex=state.drawPoints.length-1;state.draftGeometryChanged=true;}updateDrawing();}
function finishVertexDrag(){if(!vertexDrag)return;if(vertexDrag.pan)map.dragPan?.enable();suppressDraftClick=vertexDrag.moved;vertexDrag=null;if(state.drawing)updateDrawing();if(mapLoaded)map.getCanvas().style.cursor=state.drawing?'crosshair':'';}
function installDraftEditing(){
 map.on('mousedown',e=>{if(!state.drawing||e.originalEvent?.button!==0)return;const i=nearestVertex(e.point);if(i<0)return;state.selectedVertex=i;vertexDrag={i,point:[...state.drawPoints[i]],pan:map.dragPan?.isEnabled(),moved:false};map.dragPan?.disable();map.getCanvas().style.cursor='grabbing';e.preventDefault?.();updateDrawing();});
 map.on('mousemove',e=>{if(!vertexDrag||!state.drawing)return;if(!vertexDrag.moved)rememberDraw({kind:'move',index:vertexDrag.i,point:vertexDrag.point});state.drawPoints[vertexDrag.i]=[e.lngLat.lng,e.lngLat.lat];vertexDrag.moved=true;state.draftGeometryChanged=true;updateDrawing(true);});map.on('mouseup',finishVertexDrag);document.addEventListener('mouseup',finishVertexDrag);
}




async function viewDraft(id){if(!await showRealMap())return;const d=state.drafts.find(x=>x.id===id);if(!d)return;closeModal();closeDetail();enterExplore('all');$('#sidebar').hidden=true;const geometry=d.segments?.length>1?{type:'MultiLineString',coordinates:d.segments}:{type:'LineString',coordinates:d.coordinates};const f={type:'Feature',properties:{},geometry};if(mapLoaded){map.getSource('draft-route').setData(f);fitFeature(f);showLegend(`${esc(d.name)} · ${tr(d.kind==='manual'?'manual':'imported')}`)}toast(tr(d.kind==='manual'?'manual':'imported'))}
function download(name,text,type){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function draftGpx(d){const segments=d.segments||[d.coordinates];return `<?xml version="1.0" encoding="UTF-8"?><gpx version="1.1" creator="Dr Nature wiki" xmlns="http://www.topografix.com/GPX/1/1"><metadata><name>${esc(d.name)}</name><desc>${d.kind==='manual'?'Manual draft with straight segments. NOT a validated navigable trail.':'User imported track. Not validated by Dr Nature wiki.'}</desc></metadata><trk><name>${esc(d.name)}</name>${segments.map(points=>`<trkseg>${points.map(c=>`<trkpt lat="${c[1]}" lon="${c[0]}">${Number.isFinite(c[2])?`<ele>${c[2]}</ele>`:''}</trkpt>`).join('')}</trkseg>`).join('')}</trk></gpx>`}
async function importGpx(file){if(!file)return;if(file.size>8*1024*1024){toast(tr('gpxLarge'));return}try{const xml=new DOMParser().parseFromString(await file.text(),'application/xml');if(xml.querySelector('parsererror')||xml.documentElement.localName!=='gpx')throw Error('Invalid XML');let containers=[...xml.getElementsByTagNameNS('*','trkseg')];if(!containers.length)containers=[...xml.getElementsByTagNameNS('*','rte')];const segments=containers.map(seg=>[...seg.children].filter(e=>['trkpt','rtept'].includes(e.localName)).map(el=>{const lon=Number(el.getAttribute('lon')),lat=Number(el.getAttribute('lat'));if(!el.hasAttribute('lon')||!el.hasAttribute('lat')||!Number.isFinite(lon)||!Number.isFinite(lat)||Math.abs(lon)>180||Math.abs(lat)>90)throw Error('Invalid coordinate');let c=[lon,lat];const ele=[...el.children].find(x=>x.localName==='ele');if(ele&&ele.textContent.trim()&&Number.isFinite(Number(ele.textContent)))c.push(Number(ele.textContent));return c})).filter(a=>a.length>1);const coords=segments.flat();if(coords.length<2||coords.length>60000)throw Error('Invalid point count');const name=xml.getElementsByTagNameNS('*','name')[0]?.textContent?.slice(0,90)||file.name.replace(/\.gpx$/i,'');const d={id:makeId(),name,kind:'imported',coordinates:coords,segments,createdAt:new Date().toISOString()};state.drafts.push(d);persist();toast(tr('gpxImported'));renderSaved()}catch(e){console.warn('Invalid GPX:',e.message);toast(tr('gpxInvalid'))}}
function validDraft(d){return d&&typeof d.name==='string'&&d.name.length<=100&&['manual','imported'].includes(d.kind)&&Array.isArray(d.coordinates)&&d.coordinates.length>=2&&d.coordinates.length<=60000&&d.coordinates.every(c=>Array.isArray(c)&&c.length>=2&&Number.isFinite(c[0])&&Number.isFinite(c[1])&&Math.abs(c[0])<=180&&Math.abs(c[1])<=90)}
async function importNotebook(file){try{
 if(file.size>12*1024*1024)throw Error('large');const d=JSON.parse(await file.text());
 if(d.app!=='Dr Nature wiki'||!Array.isArray(d.saved)||!Array.isArray(d.drafts)||d.drafts.some(x=>!validDraft(x)))throw Error('schema');
 if(d.savedTaxa&&typeof d.savedTaxa==='object')for(const[id,r]of Object.entries(d.savedTaxa))if(/^miteco:lp:[0-9]+$/.test(id)&&r&&typeof r.scientific_name==='string'&&Number.isInteger(r.chunk)&&r.chunk>=0&&r.chunk<200)state.savedTaxa[id]={id,scientific_name:r.scientific_name.slice(0,250),common_name:typeof r.common_name==='string'?r.common_name.slice(0,250):null,group:typeof r.group==='string'?r.group.slice(0,50):'',chunk:r.chunk};
 if(d.savedNatural&&typeof d.savedNatural==='object')for(const[id,r]of Object.entries(d.savedNatural))if(/^(ign|miteco):[A-Za-z0-9:_-]+$/.test(id)&&r&&typeof r.name==='string'&&typeof r.type==='string')state.savedNatural[id]={id,name:r.name.slice(0,300),type:r.type.slice(0,50),bbox:Array.isArray(r.bbox)&&r.bbox.length===4&&r.bbox.every(Number.isFinite)?r.bbox:null};
 const keys=d.saved.filter(validSavedKey);state.saved=[...new Set([...state.saved,...keys])];
 if(Array.isArray(d.collections))for(const c of d.collections){if(!c||typeof c.id!=='string'||typeof c.name!=='string'||!Array.isArray(c.keys))continue;const valid=c.keys.filter(k=>state.saved.includes(k)),existing=state.collections.find(x=>x.id===c.id);if(existing)existing.keys=[...new Set([...existing.keys,...valid])];else state.collections.push({id:c.id.slice(0,100),name:c.name.slice(0,60),keys:[...new Set(valid)]});}
 for(const x of d.drafts){const clean={id:makeId(),name:x.name,kind:x.kind,coordinates:x.coordinates,createdAt:new Date().toISOString()};if(Array.isArray(x.segments)&&x.segments.every(seg=>validDraft({...x,coordinates:seg})))clean.segments=x.segments;state.drafts.push(clean)}
 persist();$('#saved-count').textContent=state.saved.length;toast(tr('notebookImported'));renderSaved();
 }catch{toast(tr('invalidNotebook'))}}

async function flyover(id){if(!await showRealMap())return;const f=await loadTrack(id);if(!f||!mapLoaded)return;stopTour();activeTrack=id;activeFeature=f;map.getSource('selected-route').setData(f);$('#detail-panel').hidden=true;$('#sidebar').hidden=true;document.body.classList.remove('detail-open');const coords=featureCoordinates(f);if(coords.length<2)return;const cumulative=[0];for(let i=1;i<coords.length;i++)cumulative.push(cumulative[i-1]+haversine(coords[i-1],coords[i]));const total=cumulative.at(-1),tourDuration=reduced?0:Math.min(70000,Math.max(25000,total*5000));if(!tourDuration){fitFeature(f);toast(tr('viewTrack'));return}$('#tour-title').textContent=rname(routeOf(id));$('#tour-bar').hidden=false;const el=document.createElement('div');el.style.cssText='width:14px;height:14px;border-radius:50%;background:#f4ffc4;border:3px solid #324528;box-shadow:0 0 0 7px #efffa13d';tourMarker=new (map.isSoftware?SoftwareMarker:maplibregl.Marker)({element:el}).setLngLat(coords[0]).addTo(map);map.easeTo({center:coords[0],zoom:14.2,pitch:state.terrain?65:0,bearing:-15,padding:0});const start=performance.now();let lastTerrainRequest=0;const tick=now=>{if(map.isSoftware&&now-lastTerrainRequest>5000){map.scheduleLoad();lastTerrainRequest=now;}const p=Math.min((now-start)/tourDuration,1),dist=total*p;let i=1;while(i<cumulative.length-1&&cumulative[i]<dist)i++;const a=coords[i-1],b=coords[i],t=(dist-cumulative[i-1])/(cumulative[i]-cumulative[i-1]||1);const point=[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t];tourMarker?.setLngLat(point);map.jumpTo({center:point});if(p<1)tourFrame=requestAnimationFrame(tick);else stopTour()};tourFrame=requestAnimationFrame(tick)}
function stopTour(){const running=tourFrame!==null||Boolean(tourMarker);if(tourFrame!==null)cancelAnimationFrame(tourFrame);tourFrame=null;tourMarker?.remove();tourMarker=null;$('#tour-bar').hidden=true;if(running){if(state.view!=='home')$('#sidebar').hidden=false;if(state.detail){$('#detail-panel').hidden=false;document.body.classList.add('detail-open')}}}
async function handleHash(){
 if(!catalogue)return;
 const route=parseEntryRoute(location.hash);
 if(!route||openingHash===route.key)return;
 const {type,id}=route;
 if(state.detail?.type===type&&state.detail.id===id&&!$('#detail-panel').hidden)return;
 if(type==='place'&&!placeOf(id)||type==='route'&&!routeOf(id))return;
 openingHash=route.key;
 try{if(type==='natural')await openNatural(id);else await openDetail(type,id);}
 finally{if(openingHash===route.key)openingHash=null;}
}
