document.addEventListener('input',e=>{if(e.target.id==='global-search'){renderGlobalResults(e.target.value);}else if(e.target.id==='place-search'){state.query=e.target.value;renderResults()}else if(e.target.id==='relief-range'){state.exaggeration=Number(e.target.value);$('#relief-value').textContent=`×${formatN(state.exaggeration)}`;if(mapLoaded&&state.terrain)map.setTerrain({source:'terrain',exaggeration:state.exaggeration});updateStatus()}});
document.addEventListener('change',e=>{if(e.target.id==='draft-point-index'){const i=Number(e.target.value)-1;if(Number.isInteger(i)&&i>=0&&i<state.drawPoints.length){state.selectedVertex=i;updateDrawing();}return;}if(e.target.id==='draft-segment'){finishVertexDrag();state.drawSegment=Number(e.target.value);state.drawPoints=state.drawSegments[state.drawSegment];state.selectedVertex=-1;updateDrawing();return;}if(['vertex-lng','vertex-lat'].includes(e.target.id)){const lng=Number($('#vertex-lng').value),lat=Number($('#vertex-lat').value);if(state.selectedVertex>=0&&Number.isFinite(lng)&&Number.isFinite(lat)&&Math.abs(lng)<=180&&Math.abs(lat)<=90){rememberDraw({kind:'move',index:state.selectedVertex,point:[...state.drawPoints[state.selectedVertex]]});state.drawPoints[state.selectedVertex]=[lng,lat];state.draftGeometryChanged=true;updateDrawing();}return;}if(e.target.id==='collection-select'){state.activeCollection=e.target.value;renderSaved();return;}if(e.target.dataset.collectionId){const c=state.collections.find(c=>c.id===e.target.dataset.collectionId),key=e.target.dataset.key;if(c&&state.saved.includes(key)){c.keys=e.target.checked?[...new Set([...c.keys,key])]:c.keys.filter(k=>k!==key);persist();}return;}const fields={'region-filter':'region','habitat-filter':'habitat','activity-filter':'activity','distance-filter':'maxDistance','profile-filter':'profile','duration-filter':'maxDuration','ascent-filter':'maxAscent','difficulty-filter':'difficulty'};if(fields[e.target.id]){state[fields[e.target.id]]=e.target.value;persist();renderResults()}else if(e.target.id==='geometry-filter'){state.withGeometry=e.target.checked;persist();renderResults();}else if(e.target.id==='terrain-toggle')setTerrain(e.target.checked);else if(e.target.id==='boundaries-toggle'){state.boundaries=e.target.checked;if(mapLoaded)void setBoundariesVisible(map,state.boundaries);}else if(e.target.id==='water-geometry-toggle'){state.waterGeometry=e.target.checked;geographicLayers?.setVisible({water:state.waterGeometry,protectedAreas:state.protectedGeometry});}else if(e.target.id==='protected-geometry-toggle'){state.protectedGeometry=e.target.checked;geographicLayers?.setVisible({water:state.waterGeometry,protectedAreas:state.protectedGeometry});}else if(e.target.id==='cities-toggle'){state.cities=e.target.checked;updateMarkers();}else if(e.target.id==='markers-toggle'){state.markers=e.target.checked;updateMarkers()}else if(e.target.id==='gpx-input'){importGpx(e.target.files[0]);e.target.value=''}});
document.addEventListener('submit',e=>{if(e.target.id==='collection-form'){e.preventDefault();const input=e.target.querySelector('input'),name=input.value.trim();if(name){const c={id:makeId(),name,keys:[]};state.collections.push(c);state.activeCollection=c.id;persist();renderSaved();}return;}if(e.target.id==='preferences-form'){e.preventDefault();state.profile=$('#pref-profile').value;state.activity=$('#pref-activity').value;state.maxDistance=$('#pref-distance').value;persist();closeModal();enterExplore('routes');state.filters=true;renderSidebar();toast(tr('preferencesSaved'))}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
$('#modal').addEventListener('cancel',()=>{modalKind=''});
