let mapResizeTimer;window.addEventListener('resize',()=>{clearTimeout(mapResizeTimer);mapResizeTimer=setTimeout(()=>{if(mapLoaded&&state.view!=='home'){map.resize();map.easeTo({padding:mapPadding(Boolean(state.detail)),duration:0});updateMarkers();}},120);});
