try{const responses=await Promise.all([fetch('data/catalogue.json'),fetch('data/attribution.json'),fetch('data/asset-map.json'),fetch('data/species-relations.json')]);if(responses.some(r=>!r.ok))throw Error('Catalogue request failed');const loaded=await Promise.all(responses.map(r=>r.json()));[catalogue,credits,assetMap]=loaded;speciesRelations=loaded[3].records;state.saved=state.saved.filter(validSavedKey);state.collections=state.collections.filter(c=>c&&typeof c.id==='string'&&typeof c.name==='string'&&Array.isArray(c.keys)).map(c=>({id:c.id,name:c.name.slice(0,60),keys:c.keys.filter(k=>state.saved.includes(k))}));state.drafts=state.drafts.filter(validDraft);journey=mountJourney({catalogue,assetMap,lang:state.lang,onExplore:()=>enterExplore('all')});applyLanguage();$('#global-search').disabled=false;$$('[data-init]').forEach(el=>{el.disabled=false;el.removeAttribute('data-init');});resolveCatalogue(true);handleHash();}catch(e){resolveCatalogue(false);console.error('Initialization:',e);$('#hero').innerHTML=`<h1>Dr Nature wiki</h1><p class="hero-copy">${state.lang==='es'?'No se ha podido cargar el catálogo. Recarga la página.':'The catalogue could not load. Please reload the page.'}</p><button class="button primary" data-action="reload">${tr('retry')}</button>`;$('#map-error').hidden=false;icons()}
